from __future__ import annotations

import argparse
import csv
import hashlib
import json
import os
import tempfile
import time
from contextlib import contextmanager
from dataclasses import asdict, dataclass
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Iterator

from .models import CSV_FIELDS, SUPPORTED_SCHEMA_VERSIONS

MANIFEST_VERSION = 2
_STRING_FIELDS = frozenset(
    {
        "schema_version", "capture_session_id", "source_socket_id",
        "local_event_id", "record_type", "exchange", "market", "symbol",
        "channel", "connection_id", "side", "price", "quantity", "note",
    }
)
_INT64_FIELDS = frozenset(CSV_FIELDS) - _STRING_FIELDS - {"buyer_is_maker"}
_SEQUENCED_RECORD_TYPES = frozenset(
    {
        "AGG_TRADE",
        "L2_PARTIAL",
        "L2_PARTIAL_LEVEL",
        "L2_DELTA",
        "L2_DELTA_LEVEL",
    }
)
_UNSEQUENCED_RECORD_TYPES = frozenset(
    {
        "L2_SNAPSHOT",
        "L2_SNAPSHOT_LEVEL",
        "BOOK_STATUS",
        "CONNECTION",
        "CAPTURE_STATUS",
    }
)


class ParquetStoreError(RuntimeError):
    """Fallo seguro de la conversión de un segmento cerrado."""


class SegmentBusy(ParquetStoreError):
    """Otro worker posee el segmento y no se debe duplicar el efecto."""


@dataclass(frozen=True, slots=True)
class ConversionResult:
    source: str
    parquet: str
    manifest: str
    created: bool
    row_count: int
    source_sha256: str
    parquet_sha256: str
    logical_sha256: str
    physical_order_regressions: int


def _utc_now() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def _sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _fsync_directory(path: Path) -> None:
    if not hasattr(os, "O_DIRECTORY"):
        return
    descriptor = os.open(path, os.O_RDONLY | os.O_DIRECTORY)
    try:
        os.fsync(descriptor)
    finally:
        os.close(descriptor)


def _atomic_json(path: Path, payload: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    descriptor, temporary_name = tempfile.mkstemp(
        prefix=f".{path.name}.", suffix=".tmp", dir=path.parent
    )
    try:
        with os.fdopen(descriptor, "w", encoding="utf-8") as stream:
            json.dump(payload, stream, ensure_ascii=False, sort_keys=True, indent=2)
            stream.write("\n")
            stream.flush()
            os.fsync(stream.fileno())
        os.chmod(temporary_name, 0o600)
        os.replace(temporary_name, path)
        _fsync_directory(path.parent)
    finally:
        if os.path.exists(temporary_name):
            os.unlink(temporary_name)


def _load_json(path: Path) -> dict[str, Any] | None:
    if not path.exists():
        return None
    if path.is_symlink():
        raise ParquetStoreError(f"Manifest inseguro: {path}")
    return json.loads(path.read_text(encoding="utf-8"))


def _lock_is_stale(path: Path, *, stale_after_s: float = 900.0) -> bool:
    try:
        if time.time() - path.stat().st_mtime < stale_after_s:
            return False
        payload = json.loads(path.read_text(encoding="utf-8"))
        pid = payload.get("pid")
        if not isinstance(pid, int) or pid <= 0:
            return True
        try:
            os.kill(pid, 0)
        except ProcessLookupError:
            return True
        except PermissionError:
            return False
        return False
    except (OSError, ValueError, json.JSONDecodeError):
        return True


@contextmanager
def _exclusive_lock(path: Path) -> Iterator[None]:
    path.parent.mkdir(parents=True, exist_ok=True)
    for attempt in range(2):
        try:
            descriptor = os.open(path, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
            break
        except FileExistsError as exc:
            if attempt == 0 and _lock_is_stale(path):
                path.unlink(missing_ok=True)
                continue
            raise SegmentBusy(f"Segmento ocupado: {path.name}") from exc
    else:
        raise SegmentBusy(f"Segmento ocupado: {path.name}")
    try:
        with os.fdopen(descriptor, "w", encoding="utf-8") as stream:
            stream.write(json.dumps({"pid": os.getpid(), "created_at": _utc_now()}))
            stream.flush()
            os.fsync(stream.fileno())
        yield
    finally:
        path.unlink(missing_ok=True)


def _relative_closed_csv(source: Path, source_root: Path) -> tuple[Path, Path]:
    root = source_root.resolve(strict=True)
    if source.suffix != ".csv" or source.is_symlink() or not source.is_file():
        raise ParquetStoreError(f"No es un CSV cerrado y seguro: {source}")
    resolved = source.resolve(strict=True)
    try:
        return resolved, resolved.relative_to(root)
    except ValueError as exc:
        raise ParquetStoreError(f"CSV fuera de la raíz permitida: {source}") from exc


def _validate_header(header: tuple[str, ...]) -> None:
    if header != CSV_FIELDS:
        raise ParquetStoreError("Header CSV incompatible con el esquema causal actual")


def _parse_field(field: str, value: str, line_number: int) -> str | int | bool | None:
    if field in _STRING_FIELDS:
        return value
    if field == "buyer_is_maker":
        if value == "":
            return None
        if value == "True":
            return True
        if value == "False":
            return False
        raise ParquetStoreError(f"Booleano inválido en línea {line_number}: {field}")
    if value == "":
        return None
    try:
        parsed = int(value)
    except ValueError as exc:
        raise ParquetStoreError(
            f"Entero inválido en línea {line_number}: {field}={value!r}"
        ) from exc
    if str(parsed) != value:
        raise ParquetStoreError(
            f"Entero no canónico en línea {line_number}: {field}={value!r}"
        )
    return parsed


def _logical_digest_row(digest: Any, row: dict[str, Any]) -> None:
    encoded = json.dumps(
        [row[field] for field in CSV_FIELDS],
        ensure_ascii=False,
        allow_nan=False,
        separators=(",", ":"),
    ).encode("utf-8")
    digest.update(len(encoded).to_bytes(8, "big"))
    digest.update(encoded)


def _validate_row(
    row: dict[str, Any], *, line_number: int, session_id: str | None,
    market: str | None, previous_ingest_seq: int | None,
) -> tuple[str, str, int | None, int]:
    if row["schema_version"] not in SUPPORTED_SCHEMA_VERSIONS:
        raise ParquetStoreError(f"Esquema no admitido en línea {line_number}")
    current_session = row["capture_session_id"]
    current_market = row["market"]
    record_type = row["record_type"]
    ingest_seq = row["ingest_seq"]
    if not isinstance(current_session, str) or not current_session:
        raise ParquetStoreError(f"Sesión inválida en línea {line_number}")
    if not isinstance(current_market, str) or not current_market:
        raise ParquetStoreError(f"Mercado inválido en línea {line_number}")
    if session_id is not None and current_session != session_id:
        raise ParquetStoreError("Un segmento no puede mezclar capture_session_id")
    if market is not None and current_market != market:
        raise ParquetStoreError("Un segmento no puede mezclar market")
    physical_order_regression = 0
    if record_type in _SEQUENCED_RECORD_TYPES:
        if not isinstance(ingest_seq, int) or ingest_seq <= 0:
            raise ParquetStoreError(f"ingest_seq inválido en línea {line_number}")
        # El writer conserva lotes completos, pero consumidores asíncronos
        # pueden entregarlos fuera del orden físico de recepción. Se preserva
        # ese orden como evidencia; la continuidad global la certifica audit.py.
        physical_order_regression = int(
            previous_ingest_seq is not None and ingest_seq < previous_ingest_seq
        )
        next_ingest_seq = ingest_seq
    elif record_type in _UNSEQUENCED_RECORD_TYPES:
        if ingest_seq is not None:
            raise ParquetStoreError(
                f"Fila de control con ingest_seq en línea {line_number}"
            )
        next_ingest_seq = previous_ingest_seq
    else:
        raise ParquetStoreError(
            f"record_type no admitido en línea {line_number}: {record_type}"
        )
    row_index = row["row_index"]
    if row_index is not None and (not isinstance(row_index, int) or row_index < 0):
        raise ParquetStoreError(f"row_index inválido en línea {line_number}")
    return (
        current_session,
        current_market,
        next_ingest_seq,
        physical_order_regression,
    )


def _arrow_modules() -> tuple[Any, Any]:
    try:
        import pyarrow as pa
        import pyarrow.parquet as pq
    except ImportError as exc:
        raise ParquetStoreError(
            "PyArrow no está instalado; instale la dependencia bloqueada del proyecto"
        ) from exc
    return pa, pq


def _arrow_schema(pa: Any, source_sha256: str) -> Any:
    fields = []
    for field in CSV_FIELDS:
        if field in _STRING_FIELDS:
            type_ = pa.string()
        elif field == "buyer_is_maker":
            type_ = pa.bool_()
        else:
            type_ = pa.int64()
        fields.append(pa.field(field, type_, nullable=True))
    return pa.schema(fields).with_metadata(
        {b"source_sha256": source_sha256.encode(), b"schema_version": b"2.0.0"}
    )


def _write_csv_as_parquet(
    source: Path, temporary: Path, source_sha256: str, *, batch_rows: int
) -> tuple[int, str, str, str, int]:
    pa, pq = _arrow_modules()
    schema = _arrow_schema(pa, source_sha256)
    row_count = 0
    logical_digest = hashlib.sha256()
    session_id: str | None = None
    market: str | None = None
    previous_ingest_seq: int | None = None
    physical_order_regressions = 0
    rows: list[dict[str, Any]] = []
    writer = pq.ParquetWriter(
        temporary, schema, compression="zstd", version="2.6", use_dictionary=True
    )
    try:
        with source.open("r", encoding="utf-8", newline="") as stream:
            reader = csv.DictReader(stream, restkey="__extra__")
            _validate_header(tuple(reader.fieldnames or ()))
            for line_number, raw_row in enumerate(reader, start=2):
                extra = raw_row.pop("__extra__", None)
                if extra is not None:
                    raise ParquetStoreError(f"Columnas extra en línea {line_number}")
                if any(raw_row.get(field) is None for field in CSV_FIELDS):
                    raise ParquetStoreError(f"Fila incompleta en línea {line_number}")
                row = {
                    field: _parse_field(field, raw_row[field], line_number)
                    for field in CSV_FIELDS
                }
                (
                    session_id,
                    market,
                    previous_ingest_seq,
                    physical_order_regression,
                ) = _validate_row(
                    row, line_number=line_number, session_id=session_id,
                    market=market, previous_ingest_seq=previous_ingest_seq,
                )
                physical_order_regressions += physical_order_regression
                _logical_digest_row(logical_digest, row)
                rows.append(row)
                row_count += 1
                if len(rows) >= batch_rows:
                    writer.write_table(pa.Table.from_pylist(rows, schema=schema))
                    rows.clear()
        if rows:
            writer.write_table(pa.Table.from_pylist(rows, schema=schema))
        if row_count == 0 or session_id is None or market is None:
            raise ParquetStoreError("El CSV cerrado no contiene eventos válidos")
    finally:
        writer.close()
    return (
        row_count,
        logical_digest.hexdigest(),
        session_id,
        market,
        physical_order_regressions,
    )


def _verify_parquet(
    parquet_path: Path, *, expected_rows: int, expected_digest: str,
    expected_physical_order_regressions: int, batch_rows: int,
) -> None:
    _, pq = _arrow_modules()
    parquet = pq.ParquetFile(parquet_path)
    if parquet.metadata is None or parquet.metadata.num_rows != expected_rows:
        raise ParquetStoreError("Parquet no conserva el conteo de filas")
    if tuple(parquet.schema_arrow.names) != CSV_FIELDS:
        raise ParquetStoreError("Parquet no conserva el esquema CSV causal")
    digest = hashlib.sha256()
    rows_seen = 0
    physical_order_regressions = 0
    session_id: str | None = None
    market: str | None = None
    previous_ingest_seq: int | None = None
    for batch in parquet.iter_batches(batch_size=batch_rows):
        columns = batch.to_pydict()
        for index in range(batch.num_rows):
            row = {field: columns[field][index] for field in CSV_FIELDS}
            (
                session_id,
                market,
                previous_ingest_seq,
                physical_order_regression,
            ) = _validate_row(
                row, line_number=rows_seen + 2, session_id=session_id,
                market=market, previous_ingest_seq=previous_ingest_seq,
            )
            physical_order_regressions += physical_order_regression
            _logical_digest_row(digest, row)
            rows_seen += 1
    if rows_seen != expected_rows or digest.hexdigest() != expected_digest:
        raise ParquetStoreError("Round-trip lógico CSV/Parquet no coincide")
    if physical_order_regressions != expected_physical_order_regressions:
        raise ParquetStoreError("Parquet no conserva el orden físico del CSV")


def _stat_signature(path: Path) -> tuple[int, int, int, int]:
    details = path.stat()
    return details.st_dev, details.st_ino, details.st_size, details.st_mtime_ns


def _manifest_path(relative_source: Path, manifest_root: Path) -> Path:
    identifier = hashlib.sha256(relative_source.as_posix().encode("utf-8")).hexdigest()
    return manifest_root / f"{identifier}.json"


def _clean_target_partials(target: Path) -> None:
    parent = target.parent
    if not parent.exists():
        return
    prefix = f".{target.name}."
    suffix = ".partial"
    for entry in parent.iterdir():
        if entry.is_symlink():
            continue
        if entry.is_file() and entry.name.startswith(prefix) and entry.name.endswith(suffix):
            try:
                entry.unlink(missing_ok=True)
            except OSError as exc:
                raise ParquetStoreError(
                    f"No se pudo limpiar archivo parcial huérfano: {entry}"
                ) from exc


def _result_from_manifest(payload: dict[str, Any], *, created: bool) -> ConversionResult:
    source = payload["source"]
    parquet = payload["parquet"]
    return ConversionResult(
        source=str(source["path"]), parquet=str(parquet["path"]),
        manifest=str(payload["manifest_path"]), created=created,
        row_count=int(parquet["row_count"]), source_sha256=str(source["sha256"]),
        parquet_sha256=str(parquet["sha256"]),
        logical_sha256=str(parquet["logical_sha256"]),
        physical_order_regressions=int(parquet["physical_order_regressions"]),
    )


def convert_segment(
    source: Path, *, source_root: Path, parquet_root: Path,
    manifest_root: Path, batch_rows: int = 65_536,
) -> ConversionResult:
    if batch_rows <= 0:
        raise ValueError("batch_rows debe ser positivo")
    source, relative_source = _relative_closed_csv(source, source_root)
    parquet_root.mkdir(parents=True, exist_ok=True)
    manifest_root.mkdir(parents=True, exist_ok=True)
    parquet_root = parquet_root.resolve()
    manifest_root = manifest_root.resolve()
    target = (parquet_root / relative_source).with_suffix(".parquet")
    target.parent.mkdir(parents=True, exist_ok=True)
    manifest = _manifest_path(relative_source, manifest_root)
    lock = manifest.with_suffix(".lock")
    before_signature = _stat_signature(source)
    source_sha256 = _sha256(source)
    with _exclusive_lock(lock):
        existing = _load_json(manifest)
        if target.exists():
            if target.is_symlink():
                raise ParquetStoreError(f"Parquet inseguro: {target}")
            if existing is None or existing.get("manifest_version") != MANIFEST_VERSION:
                raise ParquetStoreError("Parquet existente sin manifiesto compatible")

            state = existing.get("state")
            if state == "parquet_valid":
                if existing.get("source", {}).get("sha256") != source_sha256:
                    raise ParquetStoreError("Parquet existente sin manifiesto compatible")
                parquet = existing.get("parquet", {})
                if _sha256(target) != parquet.get("sha256"):
                    raise ParquetStoreError("Hash de Parquet existente no coincide")
                _verify_parquet(
                    target, expected_rows=int(parquet["row_count"]),
                    expected_digest=str(parquet["logical_sha256"]),
                    expected_physical_order_regressions=int(
                        parquet["physical_order_regressions"]
                    ),
                    batch_rows=batch_rows,
                )
                return _result_from_manifest(existing, created=False)
            elif state == "parquet_ready":
                if existing.get("source", {}).get("sha256") != source_sha256:
                    raise ParquetStoreError("Parquet existente con parquet_ready pero SHA de origen no coincide")
                parquet = existing.get("parquet", {})
                if _sha256(target) != parquet.get("sha256"):
                    raise ParquetStoreError("Hash de Parquet recuperado tras crash no coincide")
                _verify_parquet(
                    target, expected_rows=int(parquet["row_count"]),
                    expected_digest=str(parquet["logical_sha256"]),
                    expected_physical_order_regressions=int(
                        parquet["physical_order_regressions"]
                    ),
                    batch_rows=batch_rows,
                )
                promoted_payload = dict(existing)
                promoted_payload["state"] = "parquet_valid"
                promoted_payload["updated_at"] = _utc_now()
                promoted_payload["parquet"] = dict(promoted_payload.get("parquet", {}))
                promoted_payload["parquet"].pop("temporary_path", None)
                _fsync_directory(target.parent)
                _atomic_json(manifest, promoted_payload)
                return _result_from_manifest(promoted_payload, created=False)
            else:
                raise ParquetStoreError("Parquet existente sin manifiesto compatible")

        # El target no existe
        _clean_target_partials(target)

        base_payload: dict[str, Any] = {
            "manifest_version": MANIFEST_VERSION,
            "state": "converting",
            "updated_at": _utc_now(),
            "manifest_path": str(manifest),
            "source": {
                "path": str(source), "relative_path": relative_source.as_posix(),
                "sha256": source_sha256, "size_bytes": before_signature[2],
            },
        }
        _atomic_json(manifest, base_payload)
        descriptor, temporary_name = tempfile.mkstemp(
            prefix=f".{target.name}.", suffix=".partial", dir=target.parent
        )
        os.close(descriptor)
        temporary = Path(temporary_name)
        ready_persisted = False
        try:
            (
                row_count,
                logical_sha256,
                session_id,
                market,
                physical_order_regressions,
            ) = _write_csv_as_parquet(
                source, temporary, source_sha256, batch_rows=batch_rows
            )
            if _stat_signature(source) != before_signature:
                raise ParquetStoreError("El CSV cambió durante la conversión")
            with temporary.open("rb") as stream:
                os.fsync(stream.fileno())
            _verify_parquet(
                temporary, expected_rows=row_count,
                expected_digest=logical_sha256,
                expected_physical_order_regressions=physical_order_regressions,
                batch_rows=batch_rows,
            )
            temp_sha256 = _sha256(temporary)
            temp_size = temporary.stat().st_size
            ready_payload: dict[str, Any] = {
                "manifest_version": MANIFEST_VERSION,
                "state": "parquet_ready",
                "updated_at": _utc_now(),
                "manifest_path": str(manifest),
                "source": {
                    "path": str(source),
                    "relative_path": relative_source.as_posix(),
                    "sha256": source_sha256,
                    "size_bytes": before_signature[2],
                    "capture_session_id": session_id,
                    "market": market,
                },
                "parquet": {
                    "path": str(target),
                    "temporary_path": str(temporary),
                    "sha256": temp_sha256,
                    "row_count": row_count,
                    "logical_sha256": logical_sha256,
                    "physical_order_regressions": physical_order_regressions,
                    "physical_order_monotonic": physical_order_regressions == 0,
                    "size_bytes": temp_size,
                    "compression": "zstd",
                },
            }
            _atomic_json(manifest, ready_payload)
            ready_persisted = True

            if target.exists():
                raise ParquetStoreError("El destino apareció durante la conversión")
            os.chmod(temporary, 0o640)
            os.replace(temporary, target)
            _fsync_directory(target.parent)
        except Exception as exc:
            temporary.unlink(missing_ok=True)
            if not ready_persisted:
                base_payload.update(
                    {"state": "retryable_failure", "updated_at": _utc_now(),
                     "failure_type": type(exc).__name__}
                )
                _atomic_json(manifest, base_payload)
            raise

        valid_payload = {
            "manifest_version": MANIFEST_VERSION,
            "state": "parquet_valid",
            "updated_at": _utc_now(),
            "manifest_path": str(manifest),
            "source": ready_payload["source"],
            "parquet": dict(ready_payload["parquet"]),
        }
        valid_payload["parquet"]["path"] = str(target)
        valid_payload["parquet"]["size_bytes"] = target.stat().st_size
        valid_payload["parquet"].pop("temporary_path", None)
        _atomic_json(manifest, valid_payload)
        return _result_from_manifest(valid_payload, created=True)


def discover_closed_csv(source_root: Path) -> Iterator[Path]:
    root = source_root.resolve(strict=True)
    for candidate in sorted(root.rglob("*.csv")):
        if candidate.is_symlink() or not candidate.is_file():
            continue
        yield candidate


def convert_available(
    *, source_root: Path, parquet_root: Path, manifest_root: Path,
    max_files: int, batch_rows: int = 65_536,
) -> list[ConversionResult]:
    if max_files <= 0:
        raise ValueError("max_files debe ser positivo")
    results = []
    for source in discover_closed_csv(source_root):
        results.append(convert_segment(
            source, source_root=source_root, parquet_root=parquet_root,
            manifest_root=manifest_root, batch_rows=batch_rows,
        ))
        if len(results) >= max_files:
            break
    return results


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Convierte CSV cerrados a Parquet ZSTD sin tocar la captura"
    )
    parser.add_argument("--source-root", type=Path, required=True)
    parser.add_argument("--parquet-root", type=Path, required=True)
    parser.add_argument("--manifest-root", type=Path, required=True)
    parser.add_argument("--max-files", type=int, default=1)
    parser.add_argument("--batch-rows", type=int, default=65_536)
    args = parser.parse_args()
    try:
        results = convert_available(
            source_root=args.source_root, parquet_root=args.parquet_root,
            manifest_root=args.manifest_root, max_files=args.max_files,
            batch_rows=args.batch_rows,
        )
    except ParquetStoreError as exc:
        raise SystemExit(f"PARQUET_CONVERSION_FAILED: {exc}") from exc
    print(json.dumps([asdict(result) for result in results], ensure_ascii=False))


if __name__ == "__main__":
    main()
